action_input.code:
import os, re, json
root='.'
results={}
for dirpath,dirnames,filenames in os.walk('.'):
    for fname in filenames:
        if fname.endswith('.md') or fname.endswith('.txt') or fname.endswith('.json'):
            path=os.path.join(dirpath,fname)
            try:
                with open(path,'r',encoding='utf-8',errors='ignore') as f:
                    txt=f.read()
                if re.search(r'WBC|white blood|fibrinogen|FG|FG\b', txt, re.IGNORECASE):
                    results[path]=re.findall(r'.{0,80}(WBC|white blood|fibrinogen|FG|FG\b).{0,80}', txt, re.IGNORECASE)
            except Exception as e:
                results[path]=str(e)
print(json.dumps(results, indent=2))
print('\n--- Full knowledge.md ---\n')
print(open('knowledge.md','r',encoding='utf-8',errors='ignore').read())

